/**
 * The sending number's health: its daily limit by tier, what it has used, and the refusal when a run would go over.
 * Moved whole from broadcasts.ts (Reach out Part 2.5), which re-exports it.
 */
/** Meta's messaging-limit tiers: business-initiated conversations in a rolling day. */
declare const LIMIT_TIERS: Record<string, number>;
declare function dailyLimit(tier: string | null | undefined): number | null;
interface NumberHealthInput {
    /** Meta's quality rating as read at connection: GREEN, YELLOW, RED, UNKNOWN. */
    quality: string | null | undefined;
    /** The newest quality webhook: FLAGGED, UNFLAGGED, DOWNGRADE, UPGRADE. */
    event: string | null | undefined;
    /** The newest messaging limit webhook: TIER_250 and the like. */
    limit: string | null | undefined;
}
interface NumberHealth {
    canSend: boolean;
    tone: "ok" | "warn" | "danger" | "unknown";
    label: string;
    limitPerDay: number | null;
    refusal: string | null;
}
/**
 * The one reading of a number's health. A flagged or red number cannot
 * broadcast: sending more marketing on it risks the number itself. Anything
 * Meta has not reported is said so, never assumed good or bad.
 */
declare function numberHealth(n: NumberHealthInput): NumberHealth;
/** Null when the audience fits the day's limit; otherwise the refusal, with the numbers. */
declare function overLimitRefusal(h: NumberHealth, audience: number): string | null;

/**
 * The answer to a campaign run: a yes or a stop (the consent ledger's `contact.consent_changed`, 00013) that a run's
 * message earned. One rule, said here once: the run sheet reads it (server/campaigns/broadcasts.ts, consentAfter), and
 * `public.campaign_answers` (00403) restates it in SQL for Reports › Campaigns and the Campaigns home, which a database
 * test holds equal to this over one world. The People lens keeps every yes and stop; this is the part of them a run
 * is owed.
 *
 * An event counts only if `data.consent` is `opted_in` or `opted_out` and `data.source` is not `merge` or `stop` (a
 * merge restates the kept person's consent, a stop ends a yes: neither is the person answering); an event that names
 * no source counts. Its purpose is `email_marketing`, `marketing`, or `conversational` (any other). A send whose person
 * is not live never has an answer.
 *
 * Which run an event answers is told by a key where it carries one that names a send, else by the clock.
 * - **Exact.** An unsubscribe, a complaint or a reply no (purpose `email_marketing`, consent `opted_out`, source
 *   `unsubscribe`, `complaint` or `reply`) names the outbound email by `data.message_id`; an event of source `carrier` or
 *   `whatsapp`, of either consent (the rule does not ask `opted_out` of it), names the refused send by
 *   `data.message_external_id`. Such an event belongs to the send of the same person whose `messageId` or
 *   `messageExternalId` it names, whenever it came, and to no other run; a key that finds no send of the same person
 *   belongs to no run (it answers something else: an Inbox email, a thread's text, another person's email).
 *   - **A key is a word.** It is a JSON string that is not `''`, compared as text, exactly and case-sensitively: in SQL
 *     `messages.id::text = data->>'message_id'` (never a cast of the key to a uuid, which would turn a key that is not
 *     one into no key) and `messages.external_id = data->>'message_external_id'`, each read only where
 *     `jsonb_typeof(...) = 'string'`. A number, an object, a missing key or `''` is no key, and then the event is
 *     attributed by time; so is an event of a kind that names no key (a desk yes, an opt-in by email, an unsubscribe of
 *     another purpose, a source that is neither of the three nor `carrier`/`whatsapp`), whatever else it carries.
 * - **By time.** Every other event belongs to each send of the same person with `sentAt < at <= sentAt + REPLY_WINDOW_MS`,
 *   an `email_marketing` event only to a send that went `byEmail`.
 *
 * Per run, the answer of a person is the latest event attributed to it (by `at`, then `eventId`).
 *
 * Instants are compared at millisecond precision, both sides truncated to the millisecond (here `Date.parse`; in SQL
 * `date_trunc('milliseconds', ...)` on the event's `at` and on `sent_at`, for the window and for "the latest"). Two events at
 * the same millisecond are ordered by the greater event id as text, which for the lowercase uuids the ledger keeps is
 * uuid order.
 */
/** A campaign send, as the rule reads one: a recipient the run reached (state `sent`). */
interface AnswerSend {
    runId: string;
    contactId: string;
    sentAt: string;
    /** Reached by email: an answer about offers by email is theirs to give it, and nobody else's. */
    byEmail: boolean;
    /** The person stands: not erased, not merged into another. */
    live: boolean;
    /** The outbound email it was (`broadcast_recipients.message_id`), where one was written. */
    messageId: string | null;
    /** The provider's id for its message (`messages.external_id`), which a carrier's or WhatsApp's stop names. */
    messageExternalId: string | null;
}
/** A `contact.consent_changed` event: whose, when, and `data` as the ledger keeps it. */
interface AnswerEvent {
    id: string;
    contactId: string;
    at: string;
    data: unknown;
}
/** Which question a person's answer was to: offers, offers by email (their own answer, 00174), or everything. */
type AnswerPurpose = "marketing" | "email_marketing" | "conversational";
/** What a person answered a run: the latest event that was theirs to give it. */
interface RunAnswer {
    runId: string;
    contactId: string;
    consent: "opted_in" | "opted_out";
    purpose: AnswerPurpose;
    at: string;
    eventId: string;
    /** Found by a key the event carries, not by the clock. */
    exact: boolean;
}
/**
 * What each person answered each run: for every `(runId, contactId)` that has one, a row; in no promised order, and the
 * same rows whatever the order of `sends` and `events`.
 */
declare function answersToRuns(sends: readonly AnswerSend[], events: readonly AnswerEvent[]): RunAnswer[];

type RunFigureId = "sent" | "delivered" | "replied" | "said_yes" | "stopped";
/** The steps a figure's bars take: the canvas draws eight. */
declare const RUN_REPORT_STEPS = 8;
interface RunFigure {
    id: RunFigureId;
    label: string;
    n: number;
    /** Of what the run sent, rounded; null for "sent" itself, for none, and for a run that reached nobody. */
    pct: number | null;
    /** The sentence under the figure. */
    sub: string;
    /** "ok" for an answer that came, "warn" for a stop -- the one figure that asks the owner to look -- and plain for none. */
    tone: "plain" | "ok" | "warn";
    /** When each came back, in RUN_REPORT_STEPS equal steps from the first send across the report's span. */
    bars: number[];
}
/** The filters over "Everyone it touched". */
type RunFilterId = "all" | "replied" | "held" | "stopped";
declare const RUN_FILTERS: readonly {
    id: RunFilterId;
    label: string;
}[];
type RunTone = "plain" | "ok" | "info" | "warn" | "danger";
/** One person's line: what happened to them, in words, with the one door it offers. */
interface RunPersonVM {
    contact_id: string;
    name: string;
    /** Two letters for the mark, or a dash for someone with no name on file. */
    initials: string;
    pill: {
        label: string;
        tone: RunTone;
    };
    words: string;
    /**
     * The channel their message went by, in the words a line says it ("on WhatsApp", "by text", "by email"): said only
     * where the run reached somebody on a channel other than WhatsApp, which is every run before step 3, so a run that
     * went by WhatsApp alone says nothing of it; null for such a run, and for someone whose row names no channel.
     */
    channel: string | null;
    door: {
        label: string;
        to: string;
    } | null;
    /** The last thing that happened to them, by the business's clock; null for someone the run never sent to. */
    at: string | null;
    /** Their line asks the owner to look: a stop, or a greeting that went out "Hi there". */
    attn: boolean;
    /** The run never sent to them: held back, refused, or not yet. */
    held: boolean;
    in: RunFilterId[];
}
/** One reply, as "What came back" quotes it: their words, and what has happened since. */
interface RunReplyVM {
    contact_id: string;
    name: string;
    initials: string;
    /** Their first reply's words; null when it had none. */
    quote: string | null;
    outcome: {
        words: string;
        tone: RunTone;
    };
    to: string | null;
}
interface RunReportVM {
    figures: RunFigure[];
    /** What the bars cover, in words: "the first 4 hours" -- the shortest span holding everything heard back, up to the window. */
    span: string;
    /** How many the run was for: everyone enrolled, reached or not. */
    enrolled: number;
    /** How many each filter of "Everyone it touched" holds. */
    groups: Record<RunFilterId, number>;
    people: RunPersonVM[];
    /** Every reply, the first to come first. */
    replies: RunReplyVM[];
    /** Why a failed run stopped and how to get past it; null for a run that did not fail. */
    stop: {
        words: string;
        fix: string | null;
        tone: "warn" | "danger";
    } | null;
}
type ReportRecipient = Pick<BroadcastRecipientDto, "contact_id" | "name" | "channel" | "first_name" | "state" | "reason" | "sent_at" | "message_status" | "conversation_id" | "delivered_at" | "read_at" | "replied" | "replied_at" | "consent_after" | "consent_at" | "consent_purpose" | "reply_words" | "answered_by" | "answered_at" | "waiting_on_you">;
/**
 * Which answer a yes or a stop was, said once for a person and once for a
 * figure: a stop to offers leaves every other message going, so the canvas's
 * "they hear nothing again" is only true of a stop to everything. An answer about offers by email is the email's own
 * (the one-click unsubscribe an offer by email invites, or YES OFFERS by email): it stops or starts those alone.
 */
declare function consentAnswerWords(consent: "opted_in" | "opted_out", purpose: AnswerPurpose | null): string;
/** What happened to one person, with the times WhatsApp's receipts gave (00111): "sent 10:31 · delivered 10:32 · read 10:40 · replied 10:52". */
declare function receiptWords(r: Pick<BroadcastRecipientDto, "sent_at" | "message_status" | "delivered_at" | "read_at" | "replied" | "replied_at">, clock: (iso: string | null) => string | null): string;
/**
 * One run's report: the five figures Reports › Campaigns draws for the
 * workspace -- messages sent, delivered, replied, said yes, asked to stop --
 * scoped to this run, from its recipients; everyone it touched, each in the
 * words of what happened to them; every reply, quoted; and, for a failed run,
 * why it stopped and how to get past it.
 *
 * Delivered counts read too: a message read was delivered. Each figure's bars
 * say when its answers came, in eight equal steps from the first send across
 * the shortest span that holds everything the run heard back -- an hour, four,
 * a day, up to the reply window -- so replies that came in the first hour have
 * a shape instead of one bar, and a run whose answers trickled in over three
 * days looks like it.
 *
 * The facts are counted once (runFactsOf); each part has its builder, run in
 * the order the run has always been read.
 */
declare function toRunReportVM(d: {
    broadcast?: {
        state?: string;
        failure?: string | null;
        params?: readonly ParamSpec[];
        /** A playbook's run: which, and the moment its audience names, which a stop's next step is worded by (stoppedRunFix). */
        playbook_id?: string | null;
        audience?: unknown;
    };
    recipients: readonly ReportRecipient[];
}, opts: {
    windowMs: number;
    nowMs: number;
    clock?: (iso: string | null) => string | null;
}): RunReportVM;

declare const BROADCAST_STATES: readonly ["pending_approval", "scheduled", "sending", "sent", "canceled", "failed"];
type BroadcastState = (typeof BROADCAST_STATES)[number];
/**
 * A run that is going: scheduled, or sending. A reach-out's held emails wait for their owner's say only in a run that is
 * going (the held notice, reach-out-sheet heldNoticeDue); a run waiting for approval is counted as the run.
 */
declare const RUN_GOING_STATES: readonly ["scheduled", "sending"];
declare const RECIPIENT_STATES: readonly ["queued", "sent", "skipped", "failed"];
type RecipientState = (typeof RECIPIENT_STATES)[number];
/**
 * A reach-out's send (00183 reach_out_sends): planned (a time and a domain), claimed under the domain's capacity,
 * queued as an email row with its job, then what that row became. A wait refusal plans it again (Reach out, Part 3).
 * The check before it goes may hold it (00197): held waits for its owner, who puts it back or skips it (Part 4).
 * A hand step's lead is handed to the team, and never moves (00228, Part 5). A reach-out its owner sends hands each
 * email to them, drafted, and the owner says whether it went: sent, or skipped (00429).
 */
declare const REACH_OUT_SEND_STATES: readonly ["planned", "held", "claimed", "queued", "drafted", "sent", "skipped", "failed", "handed"];
type ReachOutSendState = (typeof REACH_OUT_SEND_STATES)[number];
/**
 * A run waiting on its owner says "Waiting for your approval", as its tab on Sent, its line on Campaigns' home, the drawer,
 * Coming up, Today's row and brief and Ask say it (lifecycle-words.ts, today-runs.ts, reach-out-approval.ts all read this
 * one). It said "Needs you" on its row's pill alone until 8 Oct 2026, which is the Inbox's word for a thread a person must
 * answer, and then "Waiting on you", which People used for a thread you have and Reports for a thread nobody has: three
 * things under one name, and a run waiting wore nine phrasings (D1-run-words). A thread is NEEDS_YOU_WORD or HELD_WORDS'
 * (conversations/standing.ts); a run is this.
 */
declare const BROADCAST_STATE_LABELS: Record<BroadcastState, string>;
/** How many go in one job, and the breath between two sends. */
declare const BROADCAST_CHUNK = 25;
declare const BROADCAST_GAP_MS = 300;
/**
 * How long a run waits each time WhatsApp says "not now" (channels graphThrottled), in order. The person the send was
 * for goes back in the queue and the run tries again after the next wait; a batch that sends without one starts the
 * count again. Past the last wait, or when the next try would fall outside the day's sending hours, the run stops and
 * says why (core messages/broadcast.ts). About an hour in all.
 */
declare const BROADCAST_THROTTLE_WAITS_MS: readonly number[];
/**
 * How long a run waits before it tries again a person it gave back because somebody holds their thread right now (a call in
 * progress, a teammate speaking: the door's `human_has_it` on a day-before reminder, which passes the 24-hour pause but not
 * a live hold, decision D4). Drawn a little longer at random. Only inside the day's sending hours: past them the person is
 * skipped, as before (core messages/broadcast.ts).
 */
declare const BROADCAST_HOLD_WAIT_MS: number;
/** More than this is not a salon's list; it is a mistake. */
declare const BROADCAST_MAX_RECIPIENTS = 2000;
/** Meta's ceiling for one body parameter. */
declare const BROADCAST_PARAM_MAX = 1024;
declare const BROADCAST_SCHEDULE_MAX_DAYS = 30;
declare const BROADCAST_NAME_MAX = 80;

/** The words a person will read: the body with its numbered slots filled. */
declare function renderTemplate(body: string | null | undefined, params: readonly string[]): string;
/**
 * One body value as Meta will accept it: trimmed, no line breaks or tabs, no
 * run of four spaces, under the ceiling. Null means "not acceptable".
 */
declare function cleanParam(raw: unknown): string | null;
/** A name when the owner gave none: the template and the day. */
declare function broadcastName(templateName: string, tz: string, now?: Date, title?: string | null): string;
interface BroadcastCounts {
    queued: number;
    sent: number;
    skipped: number;
    failed: number;
    delivered: number;
    read: number;
    replied: number;
    /**
     * What went out by each channel (0030): a recipient naming none went by WhatsApp. Absent from a read that did not
     * count them.
     */
    sent_by?: Record<ConsentChannel, number>;
}
/**
 * run_counts' answer (00374), by run id, read into Sent's counts in the order the page has always written them (a run
 * nobody is on is absent, and the caller says it as zeros), each count a whole number (isCount). Null when the answer is
 * not that shape: a read that failed, never a run with nothing in it.
 */
declare function runCountsOf(answer: unknown): Record<string, BroadcastCounts> | null;
interface BroadcastDto {
    id: string;
    name: string;
    template_id: string;
    template_name: string;
    template_language: string;
    /** What fills each numbered slot: typed text, or the person's first name, the business's name, its booking link. */
    params: ParamSpec[];
    audience: Audience;
    state: BroadcastState;
    scheduled_for: string;
    started_at: string | null;
    finished_at: string | null;
    recipient_count: number;
    failure: string | null;
    created_at: string;
    /** A playbook's run: which one, and which local day it ran for. */
    playbook_id: string | null;
    run_for: string | null;
    counts: BroadcastCounts;
    /**
     * A reach-out's run that is going: how many of its emails the check holds for its owner's say. Absent on any other run,
     * and where it could not be counted (the wiring's second audit, W-campaign-run-template-reachout-4).
     */
    held?: number;
    /** And how many are handed to its owner to send from their inbox (00429), counted as held is. */
    drafted?: number;
}
interface BroadcastVM extends BroadcastDto {
    stateLabel: string;
    /** "today 9:00 AM" / "Sep 12 · 10:00 AM". */
    when: string;
    /** Delivered or read, over sent. Null until something was sent. */
    deliveredPct: number | null;
    readPct: number | null;
    /** Still to come: scheduled or sending. */
    open: boolean;
    /** Sent + skipped + failed over enrolled, for the sending row. */
    progress: number;
    /** A failed broadcast's reason in the owner's words; null in any other state. */
    failureLabel: string | null;
}
/**
 * What a run is called where a sentence names it: its audience's label (a playbook's, a list's), else its own name. A
 * reach-out's run carries no label (core run-reach-out.ts writes its ids alone), so its name says it ("Early gyms ·
 * 2026-10-14"): read as the label alone, a line named nobody ("ran at 7:44 AM").
 */
declare function runLabelOf(run: {
    audience?: unknown;
    name: string;
}): string;
/** "today 9:00 AM" · "tomorrow 9:00 AM" · "Sep 12 · 10:00 AM", by the business's day and clock (clock.ts). */
declare function whenLabel(iso: string, tz: string, now?: Date): string;
/** What a run sent by each channel, in a line's words ("30 on WhatsApp, 6 by text"), where it went by more than one. */
declare function sentByWords(by: BroadcastCounts["sent_by"]): string | null;
declare function toBroadcastVM(d: BroadcastDto, tz: string, now?: Date): BroadcastVM;
/**
 * The recipient's row while a send is in flight — and the reason it KEEPS if
 * the run never comes back to overwrite it.
 *
 * deliver() records a broadcast's message only once the provider has accepted
 * it, so a run killed in between leaves no message row at all: a resumed run
 * would find nothing, see the person still queued, and send them the same
 * template a second time. Written before the wire is touched, this is the row
 * saying "a run was mid-send here and nobody knows how it went" — the same
 * answer the ledger gives for an outbound_send whose run did not report back.
 */
declare const OUTCOME_UNKNOWN = "outcome_unknown";
/**
 * Why an audience came out empty, in the owner's words, for the purpose they
 * actually picked.
 *
 * The route used to refuse every empty audience with "Nobody there has said yes
 * to offers yet" -- which for a `utility` template names a consent that message
 * does not need and sends the owner to record an answer that would not help.
 *
 * Written out here rather than composed from `PURPOSE_REFUSALS`, and that is a
 * decision rather than a duplication: those sentences are about ONE PERSON, for a
 * reader looking at that person ("This customer has not said yes to OFFERS"), and
 * splicing one into an audience-level refusal produces a sentence that repeats
 * itself and calls an empty set "this customer". One source of truth is for FACTS.
 * The fact here is the reason code, which both registries key on and which a test
 * holds them both complete against; the prose is written for its own reader.
 *
 * An empty audience has two causes, and only one of them is a missing yes: the
 * ones who said it may have no number to send to -- someone who has only ever
 * emailed, or a walk-in recorded with a yes and no number. That case is said in
 * People's words (`noNumberWords`, #663), naming the audience as the send screen
 * does, and without the QR, which would ask them for an answer they gave. So the
 * caller hands in the audience's name and everyone on it, before anyone is left
 * out (`audienceMembers`), and the refusal says which cause it is.
 *
 * The QR is in Sent, the ledger's "Get their yes" card since #758. These
 * words are read in a toast on the send screen, which has no QR, and in Ask,
 * which is no page at all -- so they say where it is rather than "on this page".
 *
 * A send that ticks email is said by what each channel it ticks asks of a person (consent-asks.ts, read from the one
 * predicate): by email the business's news asks a yes covering email or a relationship on record and an address that
 * works (decision D1), never "a number". WhatsApp and a text ask what they always did, in the words below.
 */
declare function emptyAudienceRefusal(purpose: AskedPurpose, label: string, pool: readonly Pick<PersonRowVM, "consent">[], how: {
    channels: readonly string[];
    about: MessageAbout;
    ready?: ChannelsReady;
}): string;
interface BroadcastRecipientDto {
    contact_id: string;
    name: string;
    /** The channel the send picked for them (step 3; reachFor); null on a run made before: WhatsApp. */
    channel?: string | null;
    /** What a first-name slot says to them, by the wire's own rule (firstNameOf) over their card as it reads now; null is "Hi there". */
    first_name: string | null;
    phone: string | null;
    state: RecipientState;
    /** Why they were held back or not reached, as the job recorded it. */
    reason: string | null;
    sent_at: string | null;
    /** The message's status from WhatsApp's receipts: sent, delivered, read, failed. */
    message_status: string | null;
    conversation_id: string | null;
    /** Their thread heard from them after the broadcast reached them. */
    replied: boolean;
    /** When WhatsApp's receipts said so (00111 stamps each status as it arrives), and when the first reply came. */
    delivered_at: string | null;
    read_at: string | null;
    replied_at: string | null;
    /**
     * What they said about hearing from the business AFTER the run reached them
     * and inside the reply window -- a yes, or a stop -- off the consent ledger
     * both doors write (00013), and when. The latest inside the window stands.
     * Null for anyone the run did not reach, or who said nothing in the window.
     */
    consent_after: "opted_in" | "opted_out" | null;
    consent_at: string | null;
    /** Which answer that was: to offers (the offers door names its purpose, 00095), or to hearing from the business at all. */
    consent_purpose: "marketing" | "email_marketing" | "conversational" | null;
    /** Their first reply's words, on one line. Null when it had none -- a photo, a voice note -- or there was no reply. */
    reply_words: string | null;
    /** Who answered that reply first, and when: the receptionist, or someone on the team. A note or a later template is not an answer. */
    answered_by: "receptionist" | "team" | null;
    answered_at: string | null;
    /** They replied, and their thread waits on a person now. */
    waiting_on_you: boolean;
}
interface BroadcastDetailDto {
    broadcast: BroadcastDto;
    recipients: BroadcastRecipientDto[];
    /** A reach-out run's own block (Reach out, Part 4 F13): its sends are reach_out_sends, never recipients. */
    reach_out?: ReachOutRunDto | null;
}

/** What a reply means, in the spec's order (§4.7). */
declare const REPLY_INTENTS: readonly ["interested", "question", "not_now", "no", "wrong_person", "away", "other"];
type ReplyIntent = (typeof REPLY_INTENTS)[number];
declare const isReplyIntent: (v: unknown) => v is ReplyIntent;
/**
 * What an owner may say the business wrote back to an email they sent from their own inbox (00429): a person's reply,
 * so never away (an automatic reply's) and never other (the model's word for mail it could not place).
 */
declare const OWNER_SAID_INTENTS: readonly ["interested", "question", "not_now", "no", "wrong_person"];
type OwnerSaidIntent = (typeof OWNER_SAID_INTENTS)[number];
/** An intent as the notice, the strip and the chip say it after "Wrote back · ". */
declare const REPLY_INTENT_WORDS: Record<ReplyIntent, string>;
/** One reading of one reply: the model's answer, parsed (parseReplyReading). */
interface ReplyReading {
    intent: ReplyIntent;
    /** At most REPLY_SUMMARY_WORDS words, in English. */
    summary: string;
    /** YYYY-MM-DD: not_now's first day to write again; away's day back. Null for every other intent. */
    day: string | null;
    /** Who they said to write to, as they wrote it: wrong_person only. */
    referTo: string | null;
    /**
     * Who signed it, as the reader found it (0052), unchecked: the person page's gate (signerOf) keeps it only when it
     * stands word for word in their own lines and is one person's own name. Null when nobody signed.
     */
    signer: {
        name: string;
        title: string | null;
    } | null;
}
/** Why a reply was not read: it is `other`, and it is read again later (G4). The table's CHECK holds the same list. */
declare const REPLY_UNREADS: readonly ["no_model", "may_not_spend", "day_spent", "model_failed"];
type Unread = (typeof REPLY_UNREADS)[number];
declare const isUnread: (v: unknown) => v is Unread;
/** Replies a workspace reads a UTC day (G4), beside the check's REACH_OUT_CHECKS_PER_DAY. */
declare const REACH_OUT_READS_PER_DAY = 200;
/** How long after a reach-out's email a reply to it is read (G5). */
