type ApiRouteKey = (typeof ROUTE_KEYS)[number];

/**
 * What a card's spec is (Ask Rewired, Phase 3, D6), and the few helpers every family of specs shares. The specs
 * themselves are one file per family beside this one; index.ts puts them together and derives the readings.
 */

/**
 * What a spec reads of what it commits: a card of Ask's, or the same act pressed on a sheet (the dashboard's
 * legacy-bridge/verbs), which is a card with no plan and no summary of its own (the sheets as verbs, 14 Oct 2026).
 */
type VerbCard = Pick<AskProposal, "id" | "payload" | "step" | "summary" | "plan"> & {
    kind: string;
};
/** The lowest role that may commit a card: its commit route's policy role. A viewer commits nothing. */
type ProposalNeeds = "operator" | "partner" | "owner";
/** The client gate (data-bits `gate`, ROLE_PERMS) a card checks before Approve; the route re-checks the role. */
type ProposalGate = "approve" | "autonomy" | "settings" | "team" | "find";
/** A window event, sent once the call that carries it lands: the surfaces a page repaints from. */
interface ProposalEvent {
    type: string;
    detail?: Record<string, unknown>;
}
/** One request a card makes: the route by its key, its params and body as the route takes them. */
interface ProposalCall {
    route: ApiRouteKey;
    params?: Record<string, string>;
    body?: unknown;
    /** The reply's: the card's id, so a second press on Approve queues no second message (D8). */
    idempotencyKey?: string;
    /** "behind": answered when the server accepts, the surfaces read again behind it (client/api.ts). */
    refresh?: "behind";
    /** What the window is told once this call lands. */
    events?: ProposalEvent[];
    /**
     * An undo's call whose row may already be gone (deleted by an earlier press of Undo whose later call was refused, or by
     * hand): its route's 404 counts as done, since what it undoes is not there, and the walk goes on. A row-scoped write
     * reads its row before its key (server/route.ts), so a pressed-again delete is never answered from the key.
     */
    goneIsDone?: true;
}
/** A call the card cannot make from this tab, in the person's words; nothing is sent. */
interface ProposalRefusal {
    refused: string;
}
/** What the tab holds that a card reads: the settings Settings loaded (`__SETTINGS`), which a settings card writes over. */
interface ProposalTab {
    settings: {
        config?: Record<string, unknown> | null;
        version?: number;
    } | null;
}
/** How the second call went, for the receipt: the first one stands either way. */
type ProposalThen = {
    ok: true;
} | {
    ok: false;
    message: string;
};
interface ProposalUndo {
    /** The undo button's words, written onto the card by its builder; null where this card has none. */
    label(p: Pick<AskProposal, "payload">): string | null;
    /**
     * How long it stays true (askUndoOpen): `cancelable` while the send's own cancel window is open; `ten_minutes`
     * for ASK_UNDO_MS; `version` for ASK_UNDO_MS and only while nobody has saved the settings since.
     */
    window: "cancelable" | "ten_minutes" | "version";
    /** What the commit keeps for the undo, from the card, the route's answer and the tab at Approve; null for none. */
    record(p: VerbCard, data: unknown, tab: ProposalTab): Record<string, unknown> | null;
    /**
     * The call that reverses it, from what the commit kept and what the tab holds now; or the calls, made in order and
     * stopping at the first refused, where what the commit made is several rows each with its own door (a message's
     * versions).
     */
    call(record: Record<string, unknown>, tab: ProposalTab): ProposalCall | readonly ProposalCall[] | ProposalRefusal;
    /** What the undo did: from the last call's answer, and what the commit kept. */
    receipt(data: unknown, record: Record<string, unknown>): string;
    /**
     * What an undo of several calls says when one after the first is refused: what the `landed` calls before it did, then
     * the refusal, so a person is never told only of the refusal after part of it went. Absent, the refusal alone.
     */
    partial?(record: Record<string, unknown>, landed: number, refused: string): string;
}
interface ProposalSpec {
    needs: ProposalNeeds;
    /** What the card does, for the refusal a member below `needs` hears: every kind above operator says it. */
    doing?: string;
    gate: ProposalGate;
    /** The call Approve makes; `tab` is what the tab held when Approve was pressed. */
    commit(p: VerbCard, tab: ProposalTab): ProposalCall | ProposalRefusal;
    /**
     * A second call on the first one's answer, or null for none: a deal's next step names the row the door wrote. A
     * refusal sends nothing and is said on the receipt as the second call's failure; the first call stands.
     */
    then?(p: VerbCard, data: unknown): ProposalCall | ProposalRefusal | null;
    receipt(p: VerbCard, data: unknown, then?: ProposalThen): string;
    /**
     * The id of what the commit made, from the route's answer, that a later step of a plan names by its token
     * (`@step:n`, contracts resolveSteps): a message's version, which a send names the message by. Absent, or null, where
     * the card makes nothing a step names.
     */
    made?(p: VerbCard, data: unknown): string | null;
    undo?: ProposalUndo;
    /** Where the card's Open goes, or null; `outcome` is what became of it. */
    open(p: Pick<AskProposal, "payload">, outcome: AskProposalOutcome | null): string | null;
}
/** A kind above operator: a member below it is refused in words, so its spec says what the card does. */
interface ProposalSpecAboveOperator extends ProposalSpec {
    needs: "partner" | "owner";
    doing: string;
}
/** The words the walk says where no spec answers. */
declare const PROPOSAL_WORDS: {
    readonly cannotApprove: "This card cannot be approved from here.";
    readonly noUndo: "This one has no undo.";
    /** A card past ASK_CARD_FRESH_MS (askCardLapsed): nothing is sent, and asking again makes it from what is true now. */
    readonly lapsed: "This card is more than a day old, and what it would change may have moved since. Ask again and it is made from how things stand now.";
    /** A plan's card past its week (askCardLapsed): the same, in the plan's words. */
    readonly planLapsed: "This plan is more than a week old, and what it would change may have moved since. Ask again and it is made from how things stand now.";
    /** A plan's card naming a step that was undone: what that step made is gone, so nothing is sent to it. */
    readonly planUndone: "A step this one builds on was undone, so what it would use is gone and nothing is sent. Ask again and the plan is made from how things stand now.";
    /** A plan's card naming a step that has made nothing yet: that step is approved first. */
    readonly waitsForStep: (n: number) => string;
    /**
     * A plan's card naming a step that was approved and made nothing it can use (a message whose every version was
     * refused): waiting would never help, so the plan is asked for again.
     */
    readonly stepMadeNothing: (n: number) => string;
    /** A plan's silent steps, stopped at step n by its refusal (`why`, in the refusal's own words): nothing after it was done. */
    readonly planStopped: (n: number, why: string) => string;
};

/**
 * Ask: the workspace assistant, as a contract.
 *
 * What lives here is everything about Ask that is pure and shared: its limits,
 * the cards (what each kind does is its spec, in ask-proposals/), the Line's
 * jump index and suggestions, and the three questions answered without a
 * model. A citation -- its kinds, the rule that keeps it honest, where a row
 * opens -- is citations.ts's; the answer -- its shape and how it is read back
 * -- ask-answer.ts's, and the format the model writes it in answer-format.ts's.
 * The route that runs the model lives in the dashboard; the Line that shows
 * the answer lives in the legacy pages; both read from here.
 *
 * This module holds the limits, the message and its cards (and what became of each), where a question is asked
 * from: the row in view (AskScope, scopeFromRoute) and the pages Ask knows it is on (ASK_SURFACES), and the shapes of
 * what a read hands a plan of Ask's (MessageRead). The rest is beside it: the languages and the guess at a question's
 * (ask-language.ts), the rules an answer's text passes (answer-text.ts), the jump index (ask-jump.ts), the suggestions
 * (ask-suggestions.ts), the three questions answered without a model (ask-fast-paths.ts) and the settings a card may
 * change (ask-settings-change.ts).
 */

/** One question, in characters. Longer than this is a document, not a question. */
declare const ASK_MAX_CHARS = 1000;
/** Tool rounds per turn: reads, then the answer, the last forced to finish. Three since the page rides in (D10). */
declare const ASK_MAX_ROUNDS = 3;
/** End to end, under the route's sixty-second ceiling. */
declare const ASK_TURN_BUDGET_MS = 45000;
/**
 * The most the owner's tools block may be, in characters as the model is sent it (66,050 on 11 October 2026; 70,426 on
 * 12 October, after the review of Ask's campaign cards, its reads and its plan; 72,542 on 13 October, the lead search
 * proposing named people at companies too, the people card's, 00430; 73,558 on 15 October, Ask reading the sequences
 * as their page does, decision 0060).
 */
declare const ASK_TOOLS_CHARS_CEILING = 74000;
/**
 * The longest the voice door lets pass with nothing speakable sent: ElevenLabs cuts a custom LLM whose stream goes
 * quiet for 15 s (its ceiling) and asks again, so while the model is quiet the door sends the vendor's own buffer words
 * every ten (docs/superpowers/specs/2026-10-03-ask-spoken-spike.md, runs B5 to B9).
 */
declare const ASK_VOICE_PULSE_MS = 10000;
/**
 * The longest the voice door waits for the model's first speakable words before it says "One moment… " itself (the
 * platform's own filler is off: its words reached the chat as the answer's head).
 */
declare const ASK_VOICE_FIRST_WORDS_MS = 2500;
/**
 * A spoken turn's claim may be taken again this long after it was made: the turn's budget and a margin, so a request
 * repeated just as the owner's budget ends is not run a second time.
 */
declare const ASK_VOICE_CLAIM_STALE_MS = 60000;
/**
 * The least life the member's token must have when a voice session starts: the session's own ceiling (ten minutes,
 * the agent's `max_duration_seconds`; elevenlabs-agent.test.mjs holds the two together) and a margin. The browser
 * refreshes a shorter one first, so the brain door opens the member to the end. It was thirty-five minutes while a
 * conversation could run thirty, which put a refresh's round trip before most presses of a one-hour token.
 */
declare const ASK_VOICE_TOKEN_MIN_MS: number;
/**
 * Ask's one voice, wherever it speaks: the agent's conversation (tooling/scripts/voice/elevenlabs-agent-config.mjs)
 * and the speech route that reads a brief or an answer aloud (apps/edge/lib/voice/ask-voice.ts). Ruben's pick, 4 Oct
 * 2026: "Mark - Natural Conversations", from the account's library. One constant, so the two never drift.
 */
declare const ASK_VOICE_ID = "UgBBYS2sOqTuMpoF3BR0";
/**
 * The model Ask's voice speaks on, in both pipes (the agent's conversation and the one-way speech): Turbo v2, the
 * one of the two the vendor allows an English agent (Turbo v2 or Flash v2) that this voice is high quality on. One
 * model, so a brief and a spoken answer sound the same. The vendor marks Turbo v2 deprecated (4 Oct 2026) and still
 * serves it, and holds the agent to it regardless; a move is one constant, after a listen.
 */
declare const ASK_VOICE_MODEL = "eleven_turbo_v2";
/** The most one speech request reads aloud: a brief runs 400 to 800 characters, an answer's say under 600. */
declare const ASK_SPEECH_MAX_CHARS = 1500;
/** What a clip read aloud is: Today's brief, or an answer's say. For the log alone; both are read the same way. */
declare const SPEECH_PURPOSES: readonly ["brief", "answer"];
type SpeechPurpose = (typeof SPEECH_PURPOSES)[number];
/**
 * How a voice session ended, the browser's word, one of a closed set the row keeps (00300, 00302): a press
 * (Clear), a typed question, another use of the voice in its place, the Line closing, the far side
 * ending it, a start that never came up, or a minute with nothing asked (`idle`, since the hold is the one mic and the
 * session waits silently between questions). The voice doctor groups by it; "stopped" said nothing.
 */
declare const VOICE_END_REASONS: readonly ["button", "typed", "superseded", "navigated", "vendor", "start", "idle"];
type VoiceEndReason = (typeof VOICE_END_REASONS)[number];
/** Whether a word is one of the set: an older bundle's, or the vendor's own, is not, and is kept on a log line alone. */
declare const isVoiceEndReason: (word: string | null | undefined) => word is VoiceEndReason;
/**
 * How long a voice session waits with nothing asked before the browser ends it (`idle`): a minute, long enough for a
 * follow-up, short enough that a session left open costs a minute of the vendor's and not ten. The agent's own
 * re-engage ("..." at its turn timeout) resets the vendor's own after-last-message clock, so this clock is the end.
 */
declare const ASK_VOICE_IDLE_MS = 60000;
/**
 * How long a lift waits for a session that is still connecting before the words go the typed way instead (the text
 * turn, then the clip): the connection starts on the press and takes two to four seconds; most holds outlast it.
 */
declare const ASK_VOICE_UP_WAIT_MS = 2500;
/** The longest a browser's timing may claim on a session's end: ten minutes, the conversation's own ceiling. */
declare const ASK_VOICE_TIMING_MAX_MS: number;
/**
 * The most one round may write: its thinking, its tool calls and its answer
 * together. One number, read by the loop's request and by the edge's clamp on
 * Ask, so the two cannot drift again: the loop asked for 2400 while the edge
 * clamped every request to 2000, so 2000 was the ceiling a round really had.
 * 4000 since the lead plan's card was cut mid-argument at 2000 (D10); an older edge clamps to its own copy.
 */
declare const ASK_MAX_TOKENS = 4000;
/**
 * The most a warm may write (server/ask/warm.ts): a warm is a turn's own head sent ahead of the question so the
 * model's cache is written before the question arrives, and what it writes back is thrown away. The API takes no
 * request for nothing at all beside an answer format and a stream, so it is the least the gateway lets a request ask
 * for; the edge clamps a warm to it, whatever the request says.
 */
declare const ASK_WARM_MAX_TOKENS = 64;
/**
 * Ask's own daily token budget per workspace, apart from the receptionist's.
 * Counted on uncached input, cache writes and output (ask_tokens_day, 00368);
 * a cache read is not counted. A write is counted because it is input the
 * model was sent, billed above uncached input: a warm (`ask_warm`) writes a
 * turn's head, some thirty thousand tokens, and counted under a hundred while
 * writes were not, so warms were the one thing the day did not bound.
 *
 * Counting them, the number doubled with them (1.5M before). A turn costs two
 * to eight thousand uncached input and output tokens, and about one question
 * in three misses the head and writes it again (the fortnight to 5 October):
 * a busy owner's sixty questions come to some 1.1M to 1.6M counted, and 1.8M
 * when every one is more than the cache's five minutes from the last. The cap
 * keeps that day inside it with room, and still stops a loop of warms at a
 * hundred heads. The first cap (400k) was spent by a day of eval runs and
 * refused the palette until the window rolled.
 */
declare const ASK_TOKENS_DAY = 3000000;
/** How much of the workspace one read may return. The words stay the pages' words. */
declare const ASK_CAPS: {
    readonly threads: 20;
    readonly messages: 30;
    readonly messagesMore: 80;
    readonly calls: 20;
    readonly transcript: 40;
    readonly people: 12;
    readonly citations: 6;
    readonly followups: 3;
    readonly needsRows: 10;
};
type AskRole = SchemaSet<"ask_messages.role">;
/**
 * The Inbox verbs the assistant may propose on a thread. One list, read by
 * the proposer on the server and the committer in the browser, so a verb
 * cannot be proposable in one and unknown to the other.
 */
