    /** Emails written. */
    written: string;
    /** Emails landed: a share of the emails written, from five. */
    delivered: string;
    /** Businesses written to, each once at its last email. */
    businesses: string;
    /** Businesses that wrote back: a share of the businesses, from five. */
    wroteBack: string;
